#!/usr/bin/env node
/**
 * Phase 276 (DOCS-03, D-16 / D-17) — build the public "Syrel API" spec from the snapshot.
 *
 * Reads  docs/public/api/openapi.snapshot.json   (regenerated by scripts/export-openapi.py;
 *                                                 kept fresh by test_276_openapi_snapshot_fresh.py)
 * Writes docs/public/api/openapi.public.json     (committed; rendered by the docs API reference)
 *
 * Everything in the output is world-readable on the docs site. The filter:
 *   - sets info.title "Syrel API", info.version from the newest RELEASED docs/history file
 *     (derived, never typed), and an info.description that states the no-API-keys truth;
 *   - drops the hidden set, including EVERY /admin path (D-16 — no operator spec is published);
 *   - badges the UI-internal set "UI-internal: may change" (D-17: /knowledge-health/* stays,
 *     the app still calls it) and every V45_OPERATIONS entry "Not yet released";
 *   - groups every surviving tag under exactly one x-tagGroups group;
 *   - adds a reusable X-Org-Id header parameter;
 *   - prunes schemas no surviving path can reach (port of canvas_gate._collect_refs/_closure).
 *   - adds NO `servers` entry: every deployment has its own host, and the reference renders with
 *     the test-request button hidden (documented deviation from the IA's step 2).
 *
 * Usage:
 *   node scripts/build-public-openapi.cjs                write the public spec
 *   node scripts/build-public-openapi.cjs --check        regenerate in memory, diff vs committed
 *   flags: --snapshot <path>  --out <path>
 *
 * Exit codes:
 *   0 — clean (written, or --check found no drift)
 *   1 — a finding ([missing-v45-op], [ungrouped-tag]) or --check drift
 *   2 — harness error (unreadable snapshot / history, too few history files parsed)
 */
"use strict"

const fs = require("fs")
const path = require("path")

const ROOT = path.resolve(__dirname, "..")
const DEFAULT_SNAPSHOT = path.join(ROOT, "docs", "public", "api", "openapi.snapshot.json")
const DEFAULT_OUT = path.join(ROOT, "docs", "public", "api", "openapi.public.json")
const DEFAULT_HISTORY = path.join(ROOT, "docs", "history")
const MIN_HISTORY_FILES = 20

const METHODS = ["get", "put", "post", "delete", "patch", "options", "head", "trace"]

const TITLE = "Syrel API"
const DESCRIPTION =
  "The HTTP API behind Syrel's own interface.\n\n" +
  "**Authentication.** Syrel has no API keys, personal access tokens or service accounts today. " +
  "A script authenticates as a signed-in user and sends that user's token " +
  "(`Authorization: Bearer <token>`). The planned answer is SEED-013 (Open Platform).\n\n" +
  "**Organizations.** Requests that act inside an organization send its id in the `X-Org-Id` header.\n\n" +
  "Operator (`/admin`) endpoints are not listed here; they answer 404 to anyone who is not an " +
  "operator, and each deployment's own signed-in API explorer documents them."

class HarnessError extends Error {}

// ── The sets (from .planning/research/docs-information-architecture.md §API reference plan) ──

/** Hidden: removed from the public document entirely. */
const HIDDEN_PREFIXES = ["/admin/", "/setup/", "/evals/", "/api/sources/", "/__test__/"]
const HIDDEN_EXACT = new Set([
  "/admin",
  "/public-config",
  "/connectors/oauth/callback",
  "/connectors/mcp/oauth/callback",
])

/** Flagged: kept, badged "UI-internal: may change" (D-17). */
const FLAGGED_EXACT = new Set([
  "/workflows/grounding-bundle",
  "/workflows/validate",
  "/threads/{thread_id}/snapshot",
  "/threads/expert-scope-preview",
  "/library/index-summary",
])
const FLAGGED_PREFIXES = ["/knowledge-health/"]

/**
 * v4.5 operations (not released). Confirmed against the snapshot 2026-10-04:
 * Phase 271 Find and Phase 270 original-file download. A listed op missing from the snapshot is
 * a finding — a stale list must never pass silently.
 */
const V45_OPERATIONS = ["post /document-search", "post /documents/{document_id}/download-url"]

/** Untagged system routes get this tag so they can be grouped. */
const SYSTEM_TAG = "system"

const TAG_GROUPS = [
  { name: "Chat & runs", tags: ["threads", "runs", "panel", "workspace", "sandbox-outputs"] },
  {
    name: "Documents",
    tags: [
      "documents",
      "takeoff",
      "document-search",
      "document-views",
      "document-relationships",
      "document-governance",
      "metadata-fields",
      "classification-rules",
      "folders",
      "kb",
      "checked-queries",
      "library",
      "knowledge-health",
    ],
  },
  {
    name: "Automation",
    tags: ["workflows", "schedules", "workflow-runs", "skills", "skill-evals", "skill-test-cases", "skill-tuner"],
  },
  { name: "Connect", tags: ["connectors", "sources"] },
  { name: "Experts", tags: ["experts"] },
  {
    name: "Account & org",
    tags: ["org", "preferences", "features", "model-registry", "settings", "audit", "feedback"],
  },
  { name: "System", tags: [SYSTEM_TAG] },
]

const BADGE_COLOR = "#F7B23B"
const BADGE_INTERNAL = { name: "UI-internal: may change", position: "after", color: BADGE_COLOR }
const BADGE_UNRELEASED = { name: "Not yet released", position: "after", color: BADGE_COLOR }
const NOTE_INTERNAL =
  "**UI-internal: may change.** This endpoint serves Syrel's own interface and is not a stable contract."
const NOTE_UNRELEASED = "**Not yet released.** Part of v4.5, which has not shipped."

const X_ORG_ID_PARAM = {
  name: "X-Org-Id",
  in: "header",
  required: false,
  description:
    "The organization this request acts in. Omit it to use your default organization. " +
    "The server checks that you belong to it.",
  schema: { type: "string", format: "uuid" },
}

// ── Helpers ────────────────────────────────────────────────────────────────────

function isHidden(p) {
  return HIDDEN_EXACT.has(p) || HIDDEN_PREFIXES.some((pre) => p.startsWith(pre))
}

function isFlagged(p) {
  return FLAGGED_EXACT.has(p) || FLAGGED_PREFIXES.some((pre) => p.startsWith(pre))
}

/** Newest released version from docs/history: "Shipped:" value must start with YYYY-MM-DD. */
function releasedVersion(historyDir) {
  let files
  try {
    files = fs.readdirSync(historyDir)
  } catch (err) {
    throw new HarnessError(`cannot read ${historyDir}: ${err.message}`)
  }
  let parsed = 0
  const released = []
  for (const f of files) {
    const m = /^v(\d+)\.(\d+)/.exec(f)
    if (!m || !f.endsWith(".md")) continue
    const third = fs.readFileSync(path.join(historyDir, f), "utf-8").split(/\r?\n/)[2] || ""
    const shipped = /\*\*Shipped:\*\*\s*(.*)$/.exec(third)
    if (!shipped) continue
    parsed += 1
    if (/^\d{4}-\d{2}-\d{2}/.test(shipped[1])) released.push([Number(m[1]), Number(m[2])])
  }
  if (parsed < MIN_HISTORY_FILES) {
    throw new HarnessError(
      `only ${parsed} docs/history files parsed (need ${MIN_HISTORY_FILES}) — refusing to derive a version`,
    )
  }
  if (released.length === 0) throw new HarnessError("no released version found in docs/history")
  released.sort((a, b) => a[0] - b[0] || a[1] - b[1])
  const [maj, min] = released[released.length - 1]
  return `${maj}.${min}`
}

const REF_PREFIX = "#/components/schemas/"

function collectRefs(node, into) {
  if (Array.isArray(node)) {
    for (const item of node) collectRefs(item, into)
  } else if (node && typeof node === "object") {
    const ref = node.$ref
    if (typeof ref === "string" && ref.startsWith(REF_PREFIX)) into.add(ref.slice(REF_PREFIX.length))
    for (const value of Object.values(node)) collectRefs(value, into)
  }
}

function closure(seed, definitions) {
  const found = new Set(seed)
  const pending = [...found]
  while (pending.length) {
    const name = pending.pop()
    const def = definitions[name]
    if (def === undefined) continue
    const nested = new Set()
    collectRefs(def, nested)
    for (const n of nested) {
      if (!found.has(n)) {
        found.add(n)
        pending.push(n)
      }
    }
  }
  return found
}

function prefixDescription(op, note) {
  op.description = op.description ? `${note}\n\n${op.description}` : note
}

// ── The build ──────────────────────────────────────────────────────────────────

/**
 * @param {object} snapshot the parsed openapi.snapshot.json (not mutated)
 * @param {{historyDir?: string}} [opts]
 * @returns {{doc: object, findings: string[]}}
 */
function buildPublicSpec(snapshot, opts = {}) {
  const historyDir = opts.historyDir || DEFAULT_HISTORY
  const src = JSON.parse(JSON.stringify(snapshot))
  const findings = []

  // 1. paths: hidden set out, badges in, system tag on untagged ops
  const paths = {}
  for (const [p, item] of Object.entries(src.paths || {})) {
    if (isHidden(p)) continue
    for (const method of METHODS) {
      const op = item[method]
      if (!op) continue
      if (!Array.isArray(op.tags) || op.tags.length === 0) op.tags = [SYSTEM_TAG]
      const badges = []
      if (isFlagged(p)) {
        badges.push({ ...BADGE_INTERNAL })
        prefixDescription(op, NOTE_INTERNAL)
      }
      if (V45_OPERATIONS.includes(`${method} ${p}`)) {
        badges.push({ ...BADGE_UNRELEASED })
        prefixDescription(op, NOTE_UNRELEASED)
      }
      if (badges.length) op["x-badges"] = badges
    }
    paths[p] = item
  }

  for (const key of V45_OPERATIONS) {
    const [method, p] = key.split(" ")
    if (!paths[p] || !paths[p][method]) findings.push(`[missing-v45-op] ${key}`)
  }

  // 2. tag groups: every used tag in exactly one group
  const used = new Set()
  for (const item of Object.values(paths)) {
    for (const method of METHODS) if (item[method]) for (const t of item[method].tags) used.add(t)
  }
  const groupOf = new Map()
  for (const g of TAG_GROUPS) for (const t of g.tags) groupOf.set(t, (groupOf.get(t) || 0) + 1)
  for (const t of [...used].sort()) {
    const n = groupOf.get(t) || 0
    if (n === 0) findings.push(`[ungrouped-tag] ${t}`)
    else if (n > 1) findings.push(`[tag-in-several-groups] ${t}`)
  }
  const tagGroups = TAG_GROUPS.map((g) => ({ name: g.name, tags: g.tags.filter((t) => used.has(t)) })).filter(
    (g) => g.tags.length > 0,
  )

  // 3. schemas: keep only the closure reachable from surviving paths
  const definitions = (src.components && src.components.schemas) || {}
  const seed = new Set()
  collectRefs(paths, seed)
  const keep = closure(seed, definitions)
  const schemas = {}
  for (const [name, def] of Object.entries(definitions)) if (keep.has(name)) schemas[name] = def

  const components = { ...(src.components || {}), schemas }
  components.parameters = { ...(components.parameters || {}), XOrgId: X_ORG_ID_PARAM }

  const doc = {
    openapi: src.openapi,
    info: { title: TITLE, version: releasedVersion(historyDir), description: DESCRIPTION },
    tags: tagGroups.flatMap((g) => g.tags.map((name) => ({ name }))),
    "x-tagGroups": tagGroups,
    paths,
    components,
  }
  return { doc, findings }
}

function serialize(doc) {
  return JSON.stringify(doc, null, 2) + "\n"
}

// ── CLI ────────────────────────────────────────────────────────────────────────

function parseArgs(argv) {
  const args = { check: false, snapshot: DEFAULT_SNAPSHOT, out: DEFAULT_OUT }
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i]
    if (a === "--check") args.check = true
    else if (a === "--snapshot") args.snapshot = path.resolve(argv[++i])
    else if (a === "--out") args.out = path.resolve(argv[++i])
    else throw new HarnessError(`unknown argument: ${a}`)
  }
  return args
}

function main(argv) {
  let args
  let snapshot
  try {
    args = parseArgs(argv)
    try {
      snapshot = JSON.parse(fs.readFileSync(args.snapshot, "utf-8"))
    } catch (err) {
      throw new HarnessError(`cannot read snapshot ${args.snapshot}: ${err.message}`)
    }
    const { doc, findings } = buildPublicSpec(snapshot)
    if (findings.length) {
      for (const f of findings) console.error(f)
      console.error(`build-public-openapi: ${findings.length} finding(s) — nothing written.`)
      return 1
    }
    const text = serialize(doc)
    const rel = path.relative(ROOT, args.out).split(path.sep).join("/")
    const srcPaths = Object.keys(snapshot.paths || {}).length
    const summary = `${Object.keys(doc.paths).length}/${srcPaths} paths, ${Object.keys(doc.components.schemas).length} schemas, version ${doc.info.version}`
    if (args.check) {
      let committed
      try {
        committed = fs.readFileSync(args.out, "utf-8")
      } catch (err) {
        console.error(`[drift] ${rel} is missing — run: node scripts/build-public-openapi.cjs`)
        return 1
      }
      if (committed.replace(/\r\n/g, "\n") !== text) {
        console.error(
          `[drift] ${rel} does not match the snapshot — run: node scripts/build-public-openapi.cjs (and commit it)`,
        )
        return 1
      }
      console.log(`build-public-openapi --check OK — ${rel} is current (${summary}).`)
      return 0
    }
    fs.writeFileSync(args.out, text)
    console.log(`wrote ${rel} (${summary}).`)
    return 0
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[HARNESS ERROR] ${err.message}`)
      return 2
    }
    console.error(`[HARNESS ERROR] ${err && err.stack ? err.stack : err}`)
    return 2
  }
}

module.exports = {
  buildPublicSpec,
  releasedVersion,
  serialize,
  V45_OPERATIONS,
  TAG_GROUPS,
  HIDDEN_PREFIXES,
  HIDDEN_EXACT,
  FLAGGED_EXACT,
  FLAGGED_PREFIXES,
}

if (require.main === module) {
  process.exit(main(process.argv.slice(2)))
}
